(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;
const canvas=document.getElementById('liquid'),ctx=canvas.getContext('2d'),hero=document.querySelector('.hero');let w=0,h=0,dpr=1,time=0,visible=true,raf=0,px=.65,py=.5;function size(){w=hero.clientWidth;h=hero.clientHeight;dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}size();addEventListener('resize',size);hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();px=e.clientX/r.width;py=(e.clientY-r.top)/r.height});
function draw(){if(!visible||document.hidden){raf=0;return}time+=.007;ctx.clearRect(0,0,w,h);const cx=w*(.66+(px-.5)*.045),cy=h*(.55+(py-.5)*.04),radius=Math.min(w*.33,h*.38);const rings=w<=800?24:46,segments=w<=800?96:150;for(let j=0;j<rings;j++){const k=j/(rings-1);ctx.beginPath();for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2;const wave=Math.sin(a*3+time)*.13+Math.cos(a*5-time*.7)*.045;const r=radius*(1+wave)*(.67+k*.43);const x=cx+Math.cos(a)*r;const y=cy+Math.sin(a)*r*.64+Math.sin(a*2+time)*radius*.09;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();const grad=ctx.createLinearGradient(cx-radius,cy-radius,cx+radius,cy+radius);grad.addColorStop(0,'rgba(255,255,255,0)');grad.addColorStop(.25,`rgba(160,160,160,${.04+k*.09})`);grad.addColorStop(.43,`rgba(255,255,255,${.1+Math.sin(k*Math.PI)*.32})`);grad.addColorStop(.51,'rgba(40,40,40,.02)');grad.addColorStop(.74,`rgba(230,230,230,${.1+k*.18})`);grad.addColorStop(1,'rgba(255,255,255,0)');ctx.strokeStyle=grad;ctx.lineWidth=1.1;ctx.stroke()}raf=requestAnimationFrame(draw)}
function resume(){if(visible&&!document.hidden&&!raf)raf=requestAnimationFrame(draw)}new IntersectionObserver(es=>{visible=es[0].isIntersecting;resume()}).observe(hero);document.addEventListener('visibilitychange',resume);resume();
const reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.journey-title,.stage,.headingrow,.products,.pricing>div:first-child').forEach(el=>{el.classList.add('motion-ready');reveal.observe(el)});
})();
